package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.BufferedReader;
import java.io.Closeable;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.cert.X509CRL;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;

import org.eclipse.kura.core.keystore.crl.CRLManager;
import org.eclipse.kura.core.keystore.util.CRLUtil;
import org.junit.After;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class CrlDownloadCancellationTest {

    private static final Logger logger = LoggerFactory.getLogger(CrlDownloadCancellationTest.class);
    private static final long TIMEOUT_MS = 5000;
    private static final String DOWNLOAD_THREAD_PREFIX = "CRLManager-download-";

    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private final List<Closeable> resources = new CopyOnWriteArrayList<>();

    private ControlledHttpServer server;
    private CompletableFuture<X509CRL> firstFetch;
    private CompletableFuture<X509CRL> secondFetch;
    private CRLManager crlManager;
    private Set<Thread> downloadThreadsBefore;

    @After
    public void tearDown() throws Exception {
        if (this.server != null) {
            this.server.releaseAll();
        }
        if (this.crlManager != null) {
            this.crlManager.close();
        }
        for (final Closeable resource : this.resources) {
            try {
                resource.close();
            } catch (final IOException e) {
                logger.debug("failed to close test resource", e);
            }
        }
        this.executor.shutdownNow();
        this.executor.awaitTermination(TIMEOUT_MS, TimeUnit.MILLISECONDS);
    }

    @Test
    public void cancellingFetchSkipsRemainingUrisAfterCurrentAttemptFails() throws Exception {
        givenControlledHttpServer();

        whenFetchWithTwoUrisIsCancelledWhileFirstIsInProgressAndFirstFails();

        thenSecondUriIsNeverRequested();
        thenExecutorWorkerIsFree();
    }

    @Test
    public void cancellingQueuedFetchPreventsItsExecution() throws Exception {
        givenControlledHttpServer();

        whenTwoFetchesAreQueuedAndSecondIsCancelledBeforeFirstFinishes();

        thenSecondUriIsNeverRequested();
        thenExecutorWorkerIsFree();
    }

    @Test
    public void closingCrlManagerStopsDownloadThreads() throws Exception {
        givenExistingDownloadThreadsRecorded();
        givenControlledHttpServer();
        givenCrlManager();

        whenDownloadStartsAndManagerIsClosedAsRequestCompletes();

        thenNoNewDownloadThreadsRemainAlive();
    }

    private void givenControlledHttpServer() throws IOException {
        this.server = new ControlledHttpServer();
        this.resources.add(this.server);
    }

    private void givenExistingDownloadThreadsRecorded() {
        this.downloadThreadsBefore = aliveDownloadThreads();
    }

    private void givenCrlManager() {
        final File storeFile = new File(this.temporaryFolder.getRoot(), "crl-store.json");
        this.crlManager = new CRLManager(storeFile, 600_000, 600_000, crl -> true, false,
                new CRLManager.Delays(50, 30_000, 50, 60_000));
    }

    private void whenFetchWithTwoUrisIsCancelledWhileFirstIsInProgressAndFirstFails() throws Exception {
        final Set<URI> uris = new LinkedHashSet<>();
        uris.add(this.server.uri("/first.crl"));
        uris.add(this.server.uri("/second.crl"));

        this.firstFetch = CRLUtil.fetchCRL(uris, this.executor);
        assertTrue(this.server.awaitFirstRequest(TIMEOUT_MS));
        assertTrue(this.firstFetch.cancel(true));
        this.server.releaseAll();
    }

    private void whenTwoFetchesAreQueuedAndSecondIsCancelledBeforeFirstFinishes() throws Exception {
        this.firstFetch = CRLUtil.fetchCRL(Collections.singleton(this.server.uri("/first.crl")), this.executor);
        assertTrue(this.server.awaitFirstRequest(TIMEOUT_MS));

        this.secondFetch = CRLUtil.fetchCRL(Collections.singleton(this.server.uri("/second.crl")), this.executor);
        assertTrue(this.secondFetch.cancel(true));
        this.server.releaseAll();
    }

    private void whenDownloadStartsAndManagerIsClosedAsRequestCompletes() throws Exception {
        this.crlManager.addDistributionPoint(Collections.singleton(this.server.uri("/first.crl")));
        assertTrue(this.server.awaitFirstRequest(TIMEOUT_MS));
        this.server.releaseAll();
        this.crlManager.close();
    }

    private void thenSecondUriIsNeverRequested() throws Exception {
        thenExecutorWorkerIsFree();
        assertFalse("expected /second.crl not to be requested after cancellation",
                this.server.getRequestedPaths().contains("/second.crl"));
    }

    private void thenExecutorWorkerIsFree() throws Exception {
        final Future<Boolean> probe = this.executor.submit(() -> true);
        assertTrue(probe.get(TIMEOUT_MS, TimeUnit.MILLISECONDS));
    }

    private void thenNoNewDownloadThreadsRemainAlive() throws InterruptedException {
        final long deadline = System.currentTimeMillis() + TIMEOUT_MS;
        Set<Thread> remaining = startedDownloadThreads();
        while (!remaining.isEmpty() && System.currentTimeMillis() < deadline) {
            Thread.sleep(50);
            remaining = startedDownloadThreads();
        }
        assertTrue("download threads still alive after close: " + remaining, remaining.isEmpty());
    }

    private Set<Thread> startedDownloadThreads() {
        return aliveDownloadThreads().stream().filter(t -> !this.downloadThreadsBefore.contains(t))
                .collect(Collectors.toSet());
    }

    private static Set<Thread> aliveDownloadThreads() {
        return Thread.getAllStackTraces().keySet().stream()
                .filter(t -> t.isAlive() && t.getName().startsWith(DOWNLOAD_THREAD_PREFIX))
                .collect(Collectors.toSet());
    }

    private static final class ControlledHttpServer implements Closeable {

        private final ServerSocket serverSocket;
        private final AtomicBoolean closed = new AtomicBoolean(false);
        private final List<String> requestedPaths = new CopyOnWriteArrayList<>();
        private final List<Socket> openSockets = new CopyOnWriteArrayList<>();
        private final CountDownLatch firstRequest = new CountDownLatch(1);
        private final CountDownLatch releaseLatch = new CountDownLatch(1);
        private final ExecutorService handlers = Executors.newCachedThreadPool();

        ControlledHttpServer() throws IOException {
            this.serverSocket = new ServerSocket(0, 50, InetAddress.getLoopbackAddress());
            this.handlers.submit(this::acceptLoop);
        }

        URI uri(final String path) {
            return URI.create("http://127.0.0.1:" + this.serverSocket.getLocalPort() + path);
        }

        boolean awaitFirstRequest(final long timeoutMs) throws InterruptedException {
            return this.firstRequest.await(timeoutMs, TimeUnit.MILLISECONDS);
        }

        void releaseAll() {
            this.releaseLatch.countDown();
        }

        List<String> getRequestedPaths() {
            return this.requestedPaths;
        }

        private void acceptLoop() {
            while (!this.closed.get()) {
                try {
                    final Socket socket = this.serverSocket.accept();
                    this.openSockets.add(socket);
                    this.handlers.submit(() -> handleConnection(socket));
                } catch (final IOException e) {
                    if (this.closed.get()) {
                        return;
                    }
                }
            }
        }

        private void handleConnection(final Socket socket) {
            try {
                final String path = readRequestPath(socket);
                this.requestedPaths.add(path);
                if ("/first.crl".equals(path)) {
                    this.firstRequest.countDown();
                    this.releaseLatch.await(TIMEOUT_MS, TimeUnit.MILLISECONDS);
                }
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (final IOException e) {
                logger.debug("test server connection error", e);
            } finally {
                try {
                    socket.close();
                } catch (final IOException e) {
                    logger.debug("failed to close test socket", e);
                }
            }
        }

        private static String readRequestPath(final Socket socket) throws IOException {
            final BufferedReader reader = new BufferedReader(
                    new InputStreamReader(socket.getInputStream(), StandardCharsets.US_ASCII));
            final String requestLine = reader.readLine();
            String headerLine = reader.readLine();
            while (headerLine != null && !headerLine.isEmpty()) {
                headerLine = reader.readLine();
            }
            if (requestLine == null) {
                return "";
            }
            final String[] parts = requestLine.split(" ");
            return parts.length >= 2 ? parts[1] : requestLine;
        }

        @Override
        public void close() throws IOException {
            this.closed.set(true);
            this.releaseLatch.countDown();
            this.serverSocket.close();
            for (final Socket socket : this.openSockets) {
                try {
                    socket.close();
                } catch (final IOException e) {
                    logger.debug("failed to close test socket on server shutdown", e);
                }
            }
            this.handlers.shutdownNow();
        }
    }
}
